package edu.academic.hotel;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc;
import java.time.LocalDate; import java.util.Map;
import static org.hamcrest.Matchers.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ReservationApiIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper mapper; @Autowired RoomRepository rooms; @Autowired BookingRepository bookings; @Autowired CustomerRepository customers; LocalDate in;
 @BeforeEach void reset(){bookings.deleteAll();customers.deleteAll();in=LocalDate.now().plusDays(60);}
 String body(Room r,LocalDate start,LocalDate end,int guests,String email)throws Exception{return mapper.writeValueAsString(Map.of("roomId",r.id,"fullName","Casey Guest","email",email,"phoneNumber","555-0188","checkInDate",start,"checkOutDate",end,"numberOfGuests",guests));}
 @Test void contextLoadsAndRoomsAreSeeded()throws Exception{mvc.perform(get("/")).andExpect(status().isOk()).andExpect(content().string(containsString("HAVEN")));mvc.perform(get("/api/rooms")).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(greaterThanOrEqualTo(6)));}
 @Test void customerCreationRejectsDuplicatesAndInvalidEmail()throws Exception{String payload="{\"fullName\":\"Casey Guest\",\"email\":\"casey@example.com\",\"phoneNumber\":\"555-0188\"}";mvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(payload)).andExpect(status().isCreated());mvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(payload)).andExpect(status().isConflict());mvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content("{\"fullName\":\"X\",\"email\":\"bad\",\"phoneNumber\":\"\"}")).andExpect(status().isBadRequest());}
 @Test void bookingPriceOverlapCancellationAndRebooking()throws Exception{Room room=rooms.findAll().get(0);String response=mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in,in.plusDays(3),2,"one@example.com"))).andExpect(status().isCreated()).andExpect(jsonPath("$.totalPrice").value(room.pricePerNight.multiply(java.math.BigDecimal.valueOf(3)).doubleValue())).andReturn().getResponse().getContentAsString();String ref=mapper.readTree(response).get("bookingReference").asText();mvc.perform(get("/api/bookings")).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(1));mvc.perform(get("/api/bookings/{reference}",ref)).andExpect(status().isOk()).andExpect(jsonPath("$.bookingReference").value(ref));mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in.plusDays(1),in.plusDays(2),1,"two@example.com"))).andExpect(status().isConflict());mvc.perform(patch("/api/bookings/{reference}/cancel",ref)).andExpect(status().isOk()).andExpect(jsonPath("$.bookingStatus").value("CANCELLED"));mvc.perform(get("/api/bookings/{reference}",ref)).andExpect(status().isOk()).andExpect(jsonPath("$.bookingStatus").value("CANCELLED"));mvc.perform(patch("/api/bookings/{reference}/cancel",ref)).andExpect(status().isConflict());mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in.plusDays(1),in.plusDays(2),1,"two@example.com"))).andExpect(status().isCreated());}
 @Test void validatesDatesCapacityAndHalfOpenAvailability()throws Exception{Room room=rooms.findAll().get(0);mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in,in,1,"invalid@example.com"))).andExpect(status().isBadRequest());mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,LocalDate.now().minusDays(1),LocalDate.now(),1,"past@example.com"))).andExpect(status().isBadRequest());if(room.capacity<4)mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in,in.plusDays(1),room.capacity+1,"capacity@example.com"))).andExpect(status().isBadRequest());mvc.perform(post("/api/bookings").contentType(MediaType.APPLICATION_JSON).content(body(room,in,in.plusDays(3),1,"range@example.com"))).andExpect(status().isCreated());mvc.perform(get("/api/rooms/available").param("checkIn",in.plusDays(1).toString()).param("checkOut",in.plusDays(2).toString()).param("guests","1")).andExpect(status().isOk()).andExpect(jsonPath("$[?(@.id=="+room.id+")]").doesNotExist());mvc.perform(get("/api/rooms/available").param("checkIn",in.plusDays(3).toString()).param("checkOut",in.plusDays(4).toString()).param("guests","1")).andExpect(status().isOk()).andExpect(jsonPath("$[?(@.id=="+room.id+")]").exists());}
}


